class Socket extends EventEmitter{send(_s:any,_o:any,cb:any){cb()}pong(){}terminate(){this.emit('close')}message(v:any){this.emit('message',Buffer.from(JSON.stringify(v)),false)}}
type CaptureKind='warm'|'valid'|'empty'|'missingActivity'|'emptyBook'|'emptyBookBadFee'|'emptyBookMalformedSide'|'emptyBookBadLevel'|'emptyBookWrongIdentity'|'emptyBookOffGrid';
async function capture(root:string,kind:CaptureKind='valid',slot=START,monoOrigin=10000,epochNumber=2,protocolVersion:'v1'|'v2'='v2',selectedToken='111',marketId='123'){
 vi.useFakeTimers({toFake:['Date','setTimeout','clearTimeout']});vi.setSystemTime(slot);
 const epoch=path.join(root,'epoch-'+String(epochNumber).padStart(6,'0'));mkdirSync(epoch);const clock=()=>({utc:Date.now(),mono:monoOrigin+Date.now()-slot}),condition='0x'+'a'.repeat(64);
 const gamma={version:protocolVersion,id:marketId,conditionId:condition,slug:'btc-updown-5m-'+slot/1000,question:'BTC Up or Down',description:'Authored follower rules',eventStartTime:new Date(slot).toISOString(),endDate:new Date(slot+300000).toISOString(),active:true,closed:false,archived:false,acceptingOrders:true,enableOrderBook:true,negRisk:false,outcomes:'["Up","Down"]',clobTokenIds:protocolVersion==='v1'?JSON.stringify([selectedToken,'222']):'["999","888"]',positionIds:[selectedToken,'222'],orderPriceMinTickSize:.01,orderMinSize:.1,volume:kind==='missingActivity'?null:'100',liquidity:kind==='missingActivity'?null:'100',feesEnabled:true,feeSchedule:{rate:.25,exponent:1,takerOnly:true,rebateRate:0}};
 const book={version:protocolVersion==='v2'?'v2':undefined,market:condition,asset_id:selectedToken,timestamp:String(slot),hash:'authored-follower-book',bids:[{price:'0.49',size:'900'}],asks:[{price:'0.51',size:'100'}],tick_size:'0.01',min_order_size:'0.1',neg_risk:false};
 if(kind.startsWith('emptyBook'))book.asks=[];if(kind==='emptyBookMalformedSide')(book as any).bids=null;
 if(kind==='emptyBookBadLevel')book.bids[0]!.size='-1';if(kind==='emptyBookWrongIdentity')book.asset_id='999';if(kind==='emptyBookOffGrid')book.bids[0]!.price='0.491';
 const market=protocolVersion==='v2'?{t:[{t:selectedToken,o:'Up'},{t:'222',o:'Down'}],mos:.1,mts:.01,mbf:0,tbf:10,fd:{r:.25,e:1,to:true},oas:0}:{condition_id:condition,market_slug:gamma.slug,question:gamma.question,description:gamma.description,active:true,closed:false,archived:false,accepting_orders:true,enable_order_book:true,neg_risk:false,tokens:[{token_id:selectedToken,outcome:'Up'},{token_id:'222',outcome:'Down'}],minimum_order_size:.1,minimum_tick_size:.01,maker_base_fee:0,taker_base_fee:2500};
 const bodies=[gamma,market,book,{base_fee:kind==='emptyBookBadFee'?true:2500}];let n=0;const socket=new Socket();
 const c=new OperatingSourceCapture({metadataUrl:currentSlotMetadataUrl(slot),expiresUtcMs:slot+300000,freeDiskReserveBytes:0},clock,path.join(epoch,'source'),{freeDiskBytes:()=>1n<<40n,socket:()=>socket as unknown as WebSocket,request:((_u:any,_o:any,cb:any)=>{const body=json(bodies[n++]),req=new EventEmitter() as any;req.destroy=()=>{};req.end=()=>queueMicrotask(()=>{const res=new Readable({read(){}}) as any;res.statusCode=200;res.headers={'content-type':'application/json'};res.rawHeaders=[];res.complete=false;cb(res);res.push(Buffer.from(body));res.complete=true;res.push(null)});return req}) as any});
 await c.readMetadata();c.bindMarket({condition,token:selectedToken,protocolVersion});await c.readMarket();await c.readBook();await c.readFee();
 writeFileSync(path.join(epoch,'samples.ndjson'),'');
 if(kind!=='empty'&&!kind.startsWith('emptyBook')){let frames=0,samples=0;const pending=c.stream({onMessage(){frames++},onSample(at){if(kind==='warm')appendFileSync(path.join(epoch,'samples.ndjson'),JSON.stringify({number:++samples,at,processedFrames:frames,proofHeadSha256:c.proofHeadSha256()})+'\n')},shouldStop:()=>false});socket.emit('open');socket.message({...book,event_type:'book'});for(let i=0;i<30;i++)await Promise.resolve();
  if(kind==='warm')for(let second=1;second<=27;second++){await vi.advanceTimersByTimeAsync(800);socket.message({...book,event_type:'book',timestamp:String(Date.now()),hash:'warm-'+second,bids:[{price:second%3===0?'0.48':'0.49',size:'900'}]});for(let i=0;i<30;i++)await Promise.resolve();if(second===13||second>=15)socket.message({event_type:'last_trade_price',market:condition,asset_id:'111',timestamp:String(Date.now()),side:second===13?'BUY':'SELL',price:'0.50',size:second===13?'5':'100',transaction_hash:'0x'+second.toString(16).padStart(64,'0')});for(let i=0;i<30;i++)await Promise.resolve();await vi.advanceTimersByTimeAsync(200);}
  c.stop('authored_closed');await pending;}else c.stop('authored_empty');
 await c.settleCallbacks();writeFileSync(path.join(epoch,'epoch-summary.json'),json({reconciled:true,cleanupFailure:null,source:c.ledger()}));vi.useRealTimers();return epoch;
}
